der-left: 4px solid currentColor;\n\t\t\t\t\t\t\tborder-radius: 8px;\n\t\t\t\t\t\t\tbox-shadow: 0 5px 14px rgba(18, 38, 63, .05);\n\t\t\t\t\t\t\tline-height: 1.45;\n\t\t\t\t\t\t\tmargin: 8px 0 0 !important;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t.notificazap-config-form .alert-warning {\n\t\t\t\t\t\t\tbackground: #fff7e6;\n\t\t\t\t\t\t\tcolor: #9a6700;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t.notificazap-config-form .alert-success {\n\t\t\t\t\t\t\tbackground: #e9f8f4;\n\t\t\t\t\t\t\tcolor: #0a665c;\n\t\t\t\t\t\t\tfont-family: inherit !important;\n\t\t\t\t\t\t\tfont-size: 14px !important;\n\t\t\t\t\t\t\tletter-spacing: 0;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t.notificazap-config-form .fieldarea > span[id^=\"enviar_\"] {\n\t\t\t\t\t\t\tbackground: #f7fafc;\n\t\t\t\t\t\t\tborder: 1px solid #d9e2ec;\n\t\t\t\t\t\t\tborder-radius: 7px;\n\t\t\t\t\t\t\tcolor: #506174;\n\t\t\t\t\t\t\tdisplay: inline-block;\n\t\t\t\t\t\t\tfont-weight: 700;\n\t\t\t\t\t\t\tpadding: 8px 10px;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t.notificazap-config-form input[type=\"checkbox\"] {\n\t\t\t\t\t\t\taccent-color: #128c7e;\n\t\t\t\t\t\t\ttransform: scale(1.1);\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t@media (max-width: 768px) {\n\t\t\t\t\t\t\t.notificazap-config-form {\n\t\t\t\t\t\t\t\tpadding: 8px;\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t.notificazap-config-form table.form tr {\n\t\t\t\t\t\t\t\tdisplay: block;\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t.notificazap-config-form .fieldlabel,\n\t\t\t\t\t\t\t.notificazap-config-form .fieldarea {\n\t\t\t\t\t\t\t\tdisplay: block;\n\t\t\t\t\t\t\t\twidth: 100% !important;\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t.notificazap-config-actions {\n\t\t\t\t\t\t\t\tdisplay: grid;\n\t\t\t\t\t\t\t\tgrid-template-columns: 1fr;\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t.notificazap-config-actions .btn-ver-logs {\n\t\t\t\t\t\t\t\ttext-align: center;\n\t\t\t\t\t\t\t\twidth: 100%;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t</style>\n\t\t\t\t\t<div class=\"notificazap-config-actions\">\n\t\t\t\t\t\t<a href=\"" . $DOMINIO_WHMCS . "modules/addons/notificazap/logs.php\" target=\"_blank\" class=\"btn btn-primary btn-ver-logs\">Ver Logs Erros</a>\n\t\t\t\t\t\t<a href=\"" . $DOMINIO_WHMCS . "modules/addons/notificazap/logs.error.php\" target=\"_blank\" class=\"btn btn-primary btn-ver-logs\">Ver Logs Falhas</a>\n\t\t\t\t\t\t<a href=\"" . $DOMINIO_WHMCS . "modules/addons/notificazap/setar.permissoes.php\" target=\"_blank\" class=\"btn btn-primary btn-ver-logs\">Verificar Permissões</a>\n\t\t\t\t\t</div>\n\t\t\t\t<script>\n\t\t\t\t\$(function(){\n\t\t\t\t\tlet configField = \$(\"input[name=addon_notificazap_licenca], input[name=addon_notificazap_key], input[name=addon_notificazap_telefone]\").first();\n\t\t\t\t\tlet configForm = configField.closest(\"form\");\n\t\t\t\t\tif(configForm.length){\n\t\t\t\t\t\tconfigForm.addClass(\"notificazap-config-form\");\n\t\t\t\t\t}\n\t\t\t\t});\n\n\t\t\t\tfunction isCheckedOptPayment(method){\n\t\t\t\t\tlet labelOptPaymentMethod = \$(\"#\" + method).parent();\n\t\t\t\t\tlet inputOptPaymentMethod = \$(labelOptPaymentMethod).children()[1];\n\t\t\t\t\tlet isChecked      = \$(inputOptPaymentMethod).is(\":checked\");\r\n\t\t\t\t\tif(!isChecked){\r\n\t\t\t\t\t\ttoggleFieldsPaymentMethod(\".toggle_\" + method,0)\r\n\t\t\t\t\t}\r\n\t\t\t\t\t\$(inputOptPaymentMethod).click(()=>{\r\n\t\t\t\t\t\ttoggleFieldsPaymentMethod(\".toggle_\" + method,250)\r\n\t\t\t\t\t\t})\r\n\t\t\t\t\t}\r\n\t\t\t\t\tfunction toggleFieldsPaymentMethod(method, timeToggle){\r\n\t\t\t\t\t\tlet fields = \$(method);\r\n\t\t\t\t\t\tfields.each((i, field)=>{\r\n\t\t\t\t\t\t\tlet rowField = \$(field).parents()[1];\r\n\t\t\t\t\t\t\t\$(rowField).fadeToggle(timeToggle);\r\n\t\t\t\t\t\t\t})\r\n\r\n\t\t\t\t\t\t}\r\n\t\t\t\t\t\tisCheckedOptPayment(\"enviar_boleto\")\r\n\t\t\t\t\t\tisCheckedOptPayment(\"enviar_codigo_barra\")\r\n\t\t\t\t\t\tisCheckedOptPayment(\"enviar_qrcode\")\r\n\t\t\t\t\t\tisCheckedOptPayment(\"enviar_copia_cola\")\r\n\t\t\t\t\t\tisCheckedOptPayment(\"enviar_chave_pix\")\r\n\t\t\t\t\t\tisCheckedOptPayment(\"enviar_link_cartao\")\r\n\t\t\t\t\t\t</script>"]]];
}
function notificazap_activate()
{
    try {
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_templates");
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_logs");
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_cron");
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_registry");
        NOTIFICAZAP_verify_Table();
        return ["status" => "success", "description" => "Módulo ativado com sucesso."];
    } catch (Exception $e) {
        return ["status" => "error", "description" => "Erro ao ativar o modulo, debug: " . $e->getMessage()];
    }
}
function notificazap_deactivate()
{
    try {
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_templates");
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_logs");
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_cron");
        WHMCS\Database\Capsule::schema()->dropIfExists("mod_notificazap_registry");
        return ["status" => "success", "description" => "Módulo desativado com sucesso."];
    } catch (Exception $e) {
        return ["status" => "error", "description" => "Ocorreu um erro ao desativar o módulo, debug: " . $e->getMessage()];
    }
}
function notificazap_output($vars)
{
    $core = new notificazapCore();
    $version = $core->NOTIFICAZAP_Pega_Versao("https://painel.modulespay.com.br/versao/v_notificazap.txt");
    $DOMINIO_WHMCS = $core->NOTIFICAZAP_Pega_Info_tblconfiguration("SystemURL");
    $statusdoservidorApi = $core->NOTIFICAZAP_EstaOnline(NZURLSERVIDORWHATSAPP);
    if (!$statusdoservidorApi) {
        $core->NOTIFICAZAP_LogWarning("Servidor do WhatsApp está offline.");
    }
    NOTIFICAZAP_verify_Table();
    $messages = WHMCS\Database\Capsule::table("mod_notificazap_templates");
    $logs = WHMCS\Database\Capsule::table("mod_notificazap_logs")->orderBy("id", "desc");
    $customfields = WHMCS\Database\Capsule::table("tblcustomfields")->where("type", "client");
    $onlineModulesPay = $core->NOTIFICAZAP_EstaOnline(NZSITEMODULESPAY);
    $licenseKeyAtual = $core->NOTIFICAZAP_Licenca();
    if ($onlineModulesPay) {
        $license = NOTIFICAZAP_check_license($licenseKeyAtual);
        $statusdalicenca = $license["status"];
    } else {
        $core->NOTIFICAZAP_LogWarning("[NOTIFICAZAP] Servidor da MODULES PAY está offline ou inacessível.");
        $license = NOTIFICAZAP_check_license($licenseKeyAtual);
        $statusdalicenca = $license["status"] ?? "Invalid";
    }
    if ($statusdalicenca !== "Active") {
        $core->NOTIFICAZAP_LogWarning("[NOTIFICA ZAP] Licença inválida ou expirada.");
    }
    $license_status = NOTIFICAZAP_status_da_licenca($license, $licenseKeyAtual, $license["checkouturl"] ?? "");
    $server_wame = $core->NOTIFICAZAP_Server();
    $key_wame = $core->NOTIFICAZAP_KEY();
    $chavekey = $core->NOTIFICAZAP_Descriptografar($key_wame);
    $tokengeral = $core->NOTIFICAZAP_Token_Geral();
    $telefoneOrigem = $core->NOTIFICAZAP_Telefone_Origem();
    $whatsapp = new notificaWhatsAppMpay($server_wame, $chavekey, $tokengeral, $telefoneOrigem);
    $qrcode = false;
    $autenticado = false;
    $conectar_telefone = false;
    $inicializar_instancia = false;
    $gerarqrcode = false;
    $serveroffline = true;
    $qrcodefade = "";
    $qrcodefadein = "";
    $templatefade = "";
    $templatefadein = "";
    $logsfade = "";
    $logsfadein = "";
    $enviosfade = "";
    $enviosfadein = "";
    $disparosfade = "";
    $disparosfadein = "";
    $disparosfade = "";
    $disparosfadein = "";
    if (isset($_GET["aba"])) {
        switch ($_GET["aba"]) {
            case "qrcode":
                $qrcodefade = "active";
                $qrcodefadein = "active in";
                break;
            case "templates":
                $templatefade = "active";
                $templatefadein = "active in";
                break;
            case "logs":
                $logsfade = "active";
                $logsfadein = "active in";
                break;
            case "envios":
                $enviosfade = "active";
                $enviosfadein = "active in";
                break;
            case "disparos":
                $disparosfade = "active";
                $disparosfadein = "active in";
                break;
        }
    } else if ($_GET["action"] === "templates") {
        $templatefade = "active";
        $templatefadein = "active in";
    } else {
        $qrcodefade = "active";
        $qrcodefadein = "active in";
    }
    if (isset($_GET["outputaction"])) {
        switch ($_GET["outputaction"]) {
            case "desconectar":
                if ($statusdoservidorApi) {
                    $whatsapp->LogoutInstance();
                    $whatsapp->DeleteInstance();
                }
                $qrcodefade = "active";
                $qrcodefadein = "active in";
                break;
            case "removerinstancia":
                if ($statusdoservidorApi) {
                    $desconectar = $whatsapp->RestartInstance();
                }
                $qrcodefade = "active";
                $qrcodefadein = "active in";
                break;
            case "deletarlog":
                WHMCS\Database\Capsule::table("mod_notificazap_logs")->delete();
                $logsfade = "active";
                $logsfadein = "active in";
                break;
        }
    }
    if ($_GET["outputaction"] == "manualmessage") {
        $corpo_mensagem = $_GET["message"];
        $userId = $_GET["userid"];
        $information = $whatsapp->getInformation();
        $Conexao = $whatsapp->connectionStatus();
        if ($information["status"] == 200 && $Conexao["instance"]["state"] == "open") {
            $DOMINIO_WHMCS = $core->NOTIFICAZAP_Pega_Info_tblconfiguration("SystemURL");
            $client = WHMCS\User\Client::find($userId);
            $corpo_mensagem = str_replace("%name%", $client->firstname, $corpo_mensagem);
            $corpo_mensagem = str_replace("%email%", $client->email, $corpo_mensagem);
            $corpo_mensagem = str_replace("%dominio%", $DOMINIO_WHMCS, $corpo_mensagem);
            $phone = $core->NOTIFICAZAP_AdjustNumber($client);
            $phone_whatsapp = $whatsapp->Valida_Number_WhatsApp($phone);
            $existsPhone = $phone_whatsapp[0]["exists"] ?? NULL;
            if (!$existsPhone) {
                $core->NOTIFICAZAP_LogWarning("Número de telefone não é WhatsApp válido", ["phone" => $phone, "action" => "manual_message_send"]);
                return NULL;
            }
            $retorno = $core->NOTIFICAZAP_EnviarMensagem($phone, $corpo_mensagem);
            if ($retorno["status"] === "success") {
                $core->NOTIFICAZAP_CadastrarLogWhatsapp($client->id, $corpo_mensagem, "sendmessage");
                echo json_encode(["status" => "success", "message" => "A notificação foi enviada com sucesso!"]);
                exit;
            }
            $erroMensagem = $retorno["error"] ?? "Erro desconhecido ao enviar a notificação.";
            echo json_encode(["status" => "error", "message" => "Erro ao enviar a notificação para o cliente! " . $erroMensagem]);
            exit;
        }
