function NOTIFICAZAP_EstaOnline2($url)
{
    $ch = curl_init($url);
    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 12, CURLOPT_CONNECTTIMEOUT => 8, CURLOPT_FOLLOWLOCATION => true, CURLOPT_SSL_VERIFYPEER => false, CURLOPT_USERAGENT => "Mozilla/5.0"]);
    $result = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $error = curl_error($ch);
    curl_close($ch);
    if ($result !== false && 200 <= $code && $code < 400) {
        return true;
    }
    $host = parse_url($url, PHP_URL_HOST);
    $ips = dns_get_record($host, DNS_A);
    foreach ($ips as $record) {
        $ip = $record["ip"] ?? $record["ipv4"] ?? NULL;
        if (!$ip) {
        } else {
            $ch = curl_init("https://" . $ip . "/");
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 12, CURLOPT_FOLLOWLOCATION => true, CURLOPT_SSL_VERIFYPEER => false, CURLOPT_HTTPHEADER => ["Host: " . $host]]);
            $result = curl_exec($ch);
            $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            if ($result !== false && 200 <= $code && $code < 400) {
                return true;
            }
        }
    }
    return false;
}

